steps.script:
var gs = GameState
var done_units = ["U_BLADE_CHAMPION_A","U_CALADIUS_GRAV-TANK_E","U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H","U_TELEMON_HEAVY_DREADNOUGHT_I","U_WITCHSEEKERS_C","U_WITCHSEEKERS_D","U_BATTLEWAGON_G","U_BOYZ_E","U_BOYZ_F","U_STRIKE_FORCE_A","U_WARBOSS_B","U_WARBOSS_C","U_WARBOSS_IN_MEGA_ARMOUR_D"]
for uid in done_units:
	gs.state.units[uid]["status"] = GameStateData.UnitStatus.DEPLOYED
var pm = tree.root.get_node("PhaseManager")
if pm.current_phase_instance:
	pm.current_phase_instance.game_state_snapshot = gs.create_snapshot()
return true
